#include <iostream>
#include <cstdlib>
#include <pcosynchro/pcosemaphore.h>
#include <pcosynchro/pcothread.h>

const int NB_THREADS = 4;
static PcoSemaphore *sem = new PcoSemaphore(2);

void task(int tid) {
    sem->acquire();
    std::cout << "Tache " << tid << " est rentrée en SC" << std::endl;
    PcoThread::usleep((int)((float)3000000 * rand() / (RAND_MAX + 1.0)));
    std::cout << "Tache " << tid << " sort de la SC" << std::endl;
    sem->release();
}

int main(void) {
    PcoThread *threads[NB_THREADS];
    for (int i = 0; i < NB_THREADS; i++) {
        threads[i] = new PcoThread(task, i);
    }
    for (int i = 0; i < NB_THREADS; i++)
        threads[i]->join();
    return EXIT_SUCCESS;
}

class PrinterManager {
    PcoSemaphore nbPrintersSem;
    std::vector<bool> busy;
    PcoSemaphore mutex;

    unsigned giveIndex(void) {
        unsigned index = 0;
        mutex.acquire();
        // Search for first free printer
        while (busy[index])
            index += 1;
        busy[index] = true;
        mutex.release();
        return index;
    }

public:
    PrinterManager(int nbPrinters) :
        nbPrintersSem(nbPrinters), mutex(1) {
        busy.resize(nbPrinters);
        for (int i = 0; i < nbPrinters; i++)
            busy[i] = false;
    }

    // STAGE 2 (CORRECT): acquire resource semaphore FIRST, mutex INSIDE giveIndex()
    unsigned allocate(void) {
        nbPrintersSem.acquire();
        return giveIndex();
    }

    /* STAGE 3 (DEADLOCK!): holding mutex while waiting on nbPrintersSem
    unsigned allocate_BROKEN(void) {
        mutex.acquire();
        nbPrintersSem.acquire(); // Blocks while holding mutex if 0 printers free!
        return giveIndex();      // (Also note giveIndex() would re-acquire mutex if unchanged!)
    }
    */

    void giveBack(unsigned index) {
        mutex.acquire();
        busy[index] = false;
        mutex.release();
        nbPrintersSem.release();
    }
};

#include <iostream>
#include <pcosynchro/pcosemaphore.h>
#include <pcosynchro/pcothread.h>

// --- Uncoordinated (T1 || T2): I2 may run before I1 (Slide 37) ---
void T1_uncoord() { std::cout << "T1: I1" << std::endl; }
void T2_uncoord() { std::cout << "T2: I2" << std::endl; }

// --- Coordinated (T1 -> T2): I1 guaranteed before I2 (Slide 38) ---
static PcoSemaphore sync(0);

void T1() {
    PcoThread::usleep(1000000); // I_1
    std::cout << "T1: fini sleep" << std::endl;
    sync.release(); // Signal T2 that I_1 is done
}

void T2() {
    std::cout << "T2: avant acquire" << std::endl;
    sync.acquire(); // Wait until T1 finishes I_1
    std::cout << "T2: apres acquire" << std::endl; // I_2
}

int main(void) {
    PcoThread thread1(T1);
    PcoThread thread2(T2);
    thread1.join();
    thread2.join();
    return 0;
}

static PcoSemaphore arriveA(0);
static PcoSemaphore arriveB(0);

// === SOLUTION 1 (Slide 40): Symmetric release-first -> VALID ===
void myTaskA_sol1() {
    a1();
    arriveA.release();
    arriveB.acquire();
    a2();
}
void myTaskB_sol1() {
    b1();
    arriveB.release();
    arriveA.acquire();
    b2();
}

// === SOLUTION 2 (Slide 41): Asymmetric -> VALID (NO DEADLOCK!) ===
void myTaskA_sol2() {
    a1();
    arriveB.acquire(); // Waits for B to finish b1() and release arriveB
    arriveA.release(); // Signals B after both a1() and b1() are done
    a2();
}
void myTaskB_sol2() {
    b1();
    arriveB.release(); // B releases FIRST!
    arriveA.acquire(); // B waits for A
    b2();
}

// === BROKEN VARIANT (NOT Slide 41!): Symmetric acquire-first -> DEADLOCK! ===
void myTaskA_deadlock() {
    a1();
    arriveB.acquire(); // Blocks waiting for B
    arriveA.release();
    a2();
}
void myTaskB_deadlock() {
    b1();
    arriveA.acquire(); // Blocks waiting for A
    arriveB.release();
    b2();
}

#include <pcosynchro/pcosemaphore.h>
#include <thread>

class SemMutex {
    PcoSemaphore sem{1};      // Controls mutual exclusion
    PcoSemaphore stateLock{1}; // Protects owner & locked flag
    bool locked = false;
    std::thread::id owner;

public:
    void lock() {
        // Note: if the same owner calls lock() again, sem.acquire() deadlocks (non-recursive).
        sem.acquire();
        stateLock.acquire();
        locked = true;
        owner = std::this_thread::get_id();
        stateLock.release();
    }

    void unlock() {
        stateLock.acquire();
        // Preserve mutex ownership & no-memory-of-extra-unlocks semantics:
        if (locked && owner == std::this_thread::get_id()) {
            locked = false;
            owner = std::thread::id{};
            stateLock.release();
            sem.release();
            return;
        }
        stateLock.release();
    }
};

// === BROKEN: Local mutex per call (NO mutual exclusion!) ===
void tache_broken() {
    PcoMutex mutex; // Created on each thread's private stack!
    mutex.lock();
    std::cout << "Section critique" << std::endl;
    mutex.unlock();
}

// === CORRECT: static mutex shared across all threads ===
void tache_correct() {
    static PcoMutex mutex; // Single shared instance across all threads
    mutex.lock();
    std::cout << "Section critique" << std::endl;
    mutex.unlock();
}

#include <iostream>
#include <pcosynchro/pcosemaphore.h>
#include <pcosynchro/pcothread.h>

static PcoSemaphore start1(0);
static PcoSemaphore start2(0);

void task1() {
    start1.acquire(); // Wait for main's signal
    std::cout << "Task 1 running" << std::endl;
}

void task2() {
    start2.acquire(); // Wait for main's signal
    std::cout << "Task 2 running" << std::endl;
}

int main() {
    PcoThread t1(task1);
    PcoThread t2(task2);

    // Main preparation work...
    start1.release(); // Unblock task1
    start2.release(); // Unblock task2

    t1.join();
    t2.join();
    return 0;
}
